// GitHub net lines (#402) — daily additions-vs-deletions bar chart. Extracted from GitHubPulse's
// inline card into its own composable record; adds the loading + empty states the inline version didn't have.
import { useState } from "react";
import { CardHead, Bars, Legend, RangeToggle, useTip, fmt } from "@/shared/ui/charts";
import { SkeletonChart } from "@/shared/ui/feedback/Skeleton";
import { CardEmpty } from "@/shared/ui/feedback/CardStates";
import { Card } from "@/shared/ui/data/Card";

interface VelocitySlice { labels: string[]; commits: number[]; merged: number[]; opened: number[]; adds: number[]; dels: number[] }

function sliceVelocity(v: VelocitySlice, range: string): VelocitySlice {
  const n = range === "7d" ? 7 : v.labels.length;
  const last = <T,>(a: T[]) => a.slice(-n);
  return { labels: last(v.labels), commits: last(v.commits), merged: last(v.merged), opened: last(v.opened), adds: last(v.adds), dels: last(v.dels) };
}

const DEMO_VELOCITY: VelocitySlice = {
  labels: Array.from({ length: 14 }, (_, i) => `d${i + 1}`),
  commits: [3, 5, 2, 6, 4, 7, 5, 3, 6, 4, 8, 5, 6, 4],
  merged: [1, 2, 1, 3, 2, 3, 2, 1, 3, 2, 4, 2, 3, 2],
  opened: [2, 3, 2, 4, 3, 4, 3, 2, 4, 3, 5, 3, 4, 3],
  adds: [120, 200, 90, 260, 180, 300, 210, 130, 240, 170, 320, 200, 250, 180],
  dels: [40, 60, 30, 80, 50, 90, 60, 40, 70, 50, 100, 60, 80, 50],
};

export function NetLines({ velocity = DEMO_VELOCITY, partialDiffs = false, loading = false }: { velocity?: VelocitySlice; partialDiffs?: boolean; loading?: boolean }) {
  const [range, setRange] = useState("14d");
  const tip = useTip();
  const d = sliceVelocity(velocity, range);
  const total = d.adds.reduce((a, b) => a + b, 0) + d.dels.reduce((a, b) => a + b, 0);
  return (
    <Card>
      <CardHead title="Lines changed" hint={partialDiffs ? "additions vs deletions · recent commits" : "additions vs deletions / day"}
        right={<RangeToggle value={range} onChange={setRange} options={["7d", "14d"]} />} />
      {loading ? <SkeletonChart height={140} /> : total === 0 ? (
        <CardEmpty icon="○" title="No line changes yet" hint="Additions and deletions will appear here once this repo has commits." />
      ) : (
        <>
          <Bars labels={d.labels} height={140} fmtY={(v) => fmt(v)} tip={tip} groups={[
            { name: "added", color: "var(--success)", data: d.adds },
            { name: "removed", color: "var(--danger)", data: d.dels },
          ]} />
          <Legend style={{ marginTop: 8 }} items={[
            { color: "var(--success)", label: "added" },
            { color: "var(--danger)", label: "removed" },
          ]} />
        </>
      )}
      {tip.node}
    </Card>
  );
}
